    if prim is None:
        # Create the prim path
        stage.set_prim(prim_path, UsdPrim(name=prim_path.split("/")[-1]))
        prim = stage.get_prim(prim_path)
    prim.set_attr(attr_name, attr_type, value)
    write_stage(stage, filepath)


